'use strict';

// Methods of a package's JavaScript class with an untyped parameter are
// lowered once per call-site type tuple. `charAt` reads past the end of the
// buffer, which answers undefined, so the instance's result keeps that arm
// and the public wrappers hand it back.
class Cursor {
  constructor() {
    this.buffer = '';
    this.pos = 0;
  }
  setInput(src) {
    this.buffer = src;
    this.pos = 0;
  }
  charAt(n) {
    return this.buffer[this.pos + n];
  }
  startsWithDash() {
    return this.charAt(0) === '-';
  }
  charAfter(n) {
    return this.charAt(n);
  }
}

exports.Cursor = Cursor;
